/**
 * The portal's sitemaps (S15-02, PLAN §7 M14: per-locale sitemaps with hreflang): generated by a worker job into
 * object storage (the `feeds` bucket, R2 in production), served by the public pages from there — a crawler never makes
 * the portal query the database.
 *
 * **Generation** (`generatePortalSitemaps`, job `websiteApi.generatePortalSitemaps`, pool `exports`, every
 * `PORTAL_SITEMAP_EVERY_MS`): the portal's own stock — the directory-listed agencies' PUBLIC listings and developments,
 * through the same inventories as the pages (Decision S15-01: unlisted agencies' stock is never published) — walked
 * by keyset (`search.portalSitemapPage` on the public-code index; `search.developmentPage`), one short
 * `app_public` transaction and one statement per batch. Every locale's URL comes from the helpers the pages use
 * (`portalListingPaths`: each locale's own taxonomy names, by id; `portalDevelopmentPaths`), so a sitemap URL is the
 * page's canonical. Then the location and zone pages that hold any of it, and the home and search pages; S15-03: the
 * profile pages of the agencies that own any of it (`portalAgencyPaths`; names in one statement per batch). Per UI
 * locale and part (`listings`, `developments`, `places`, `agencies`), files of at most `PORTAL_SITEMAP_URLS` URLs,
 * each URL with its hreflang alternates (`xhtml:link`, `x-default` = the default UI locale), streamed through gzip
 * into a multipart upload (`GzipObjectUpload`: memory holds one batch and one upload part per open file). S16-F2: a
 * part's files are finished as soon as its walk ends, so at most one upload per UI locale is open at a time — memory
 * is bounded by the locale count, never by locales × parts. Last the index (`sitemap.xml`) and the manifest
 * (`current.json`, the run and its files' hashes) — only then does the run serve. The previous run's files are kept (a
 * public process may still read its cached manifest); the run before it is deleted, and S16-F2 so is every other run
 * prefix (`sweepPortalSitemapRuns`: the files of a run killed mid-way, which no manifest ever named). A failed run deletes its
 * own files and the previous run keeps serving. Uploads a dead worker left open are aborted by the `feeds` bucket's
 * lifecycle rule (runbook deploy.md step 6).
 *
 * **Serving** (`portalSitemapFile`): the manifest (cached in process for `MANIFEST_TTL_MS`), the file's strong ETag
 * (its gzip SHA-256), the stored gzip bytes as a stream.
 */
import type { Readable } from 'node:stream';
import type { UnitCardDoc } from '@inmolink/contracts';
import { withPublicRead } from '@inmolink/db';
import { DEFAULT_UI_LOCALE, UI_LOCALES } from '@inmolink/i18n';
import { clock } from '@inmolink/platform/clock';
import { newId } from '@inmolink/platform/ids';
import type { Logger } from '@inmolink/platform/logger';
import { MIN_UPLOAD_PART_BYTES, storage } from '@inmolink/platform/storage';
import { XmlWriter } from '@inmolink/platform/xml';
import { GzipObjectUpload } from '../../stored-feed';
import * as agencies from '../agencies';
import * as search from '../search';
import * as websites from '../websites';
import {
  contentLocale,
  developmentInventory,
  fallbackOf,
  ownView,
  type PlaceIndex,
  placeIndex,
  portalAgencyPaths,
  portalDevelopmentPaths,
  portalInventory,
  portalListingPaths,
} from './portal';
import { homePath, searchPath, zonePath } from './portal-urls';

/** URLs per sitemap file (the protocol allows 50,000; with hreflang alternates each URL is ~0.5 KB). */
export const PORTAL_SITEMAP_URLS = 10_000;
/** Listings per batch (one statement per UI locale). */
export const PORTAL_SITEMAP_BATCH = 1_000;
/** Developments per batch (each row carries a unit card). */
const DEVELOPMENT_BATCH = 200;
/** How often the sitemaps are regenerated. */
export const PORTAL_SITEMAP_EVERY_MS = 6 * 3_600_000;
/** A sitemap file's compressed size cap (the protocol's 50 MB is uncompressed; ours stay far below). */
const MAX_GZIP_BYTES = 16 * 1024 * 1024;
/** Flush the writer into its upload once it holds this many characters. */
const FLUSH_CHARS = 64 * 1024;

export const PORTAL_SITEMAP_PREFIX = 'portal-sitemaps/';
const MANIFEST_KEY = `${PORTAL_SITEMAP_PREFIX}current.json`;
const MANIFEST_MAX_BYTES = 1024 * 1024;
const fileKey = (runId: string, name: string) => `${PORTAL_SITEMAP_PREFIX}${runId}/${name}.gz`;

/** The index and every part file a request may name (`/sitemap.xml`, `/sitemaps/<locale>-<part>-<n>.xml`). */
export const PORTAL_SITEMAP_INDEX = 'sitemap.xml';
export const PORTAL_SITEMAP_FILE = /^[a-z]{2}-(?:listings|developments|places|agencies)-[1-9][0-9]{0,4}\.xml$/;

const SITEMAP_NS = 'http://www.sitemaps.org/schemas/sitemap/0.9';
const XHTML_NS = 'http://www.w3.org/1999/xhtml';

export interface PortalSitemapManifest {
  runId: string;
  generatedAt: string;
  files: { name: string; sha256: string; bytes: number; urls: number }[];
  /** The run served before this one: kept until the next run (a process may still name it). */
  previous?: { runId: string; files: string[] };
}

let origin: string | undefined;

/** Worker boot (exports pool): the portal's public origin (`PORTAL_URL`) the sitemaps' absolute URLs start with. */
export function configurePortalSitemaps(settings: { origin: string }): void {
  const url = new URL(settings.origin);
  if (url.protocol !== 'https:' && url.protocol !== 'http:') throw new Error('portal sitemaps: origin must be http(s)');
  origin = url.origin;
}

/** Whether the worker can generate sitemaps (the origin is configured). */
export const portalSitemapsConfigured = () => origin !== undefined;

type Part = 'listings' | 'developments' | 'places' | 'agencies';

/** One part's files in one locale: a new file every `PORTAL_SITEMAP_URLS` URLs. */
class PartFiles {
  readonly done: { name: string; sha256: string; bytes: number; urls: number }[] = [];
  #current: { name: string; w: XmlWriter; sink: GzipObjectUpload; urls: number } | null = null;
  #n = 0;

  constructor(
    private readonly runId: string,
    private readonly locale: string,
    private readonly part: Part,
  ) {}

  #open() {
    this.#n += 1;
    const name = `${this.locale}-${this.part}-${this.#n}.xml`;
    const sink = new GzipObjectUpload(
      storage().upload('feeds', fileKey(this.runId, name), {
        contentType: 'application/gzip',
        partBytes: MIN_UPLOAD_PART_BYTES,
      }),
      { hash: 'gzip', maxBytes: MAX_GZIP_BYTES, tooLarge: () => new Error('portal sitemap: file too large') },
    );
    const w = new XmlWriter();
    w.open('urlset', { xmlns: SITEMAP_NS, 'xmlns:xhtml': XHTML_NS }).newline();
    this.#current = { name, w, sink, urls: 0 };
    return this.#current;
  }

  /** One URL (`paths[this.locale]`) with its alternates (every locale's path) and its last change. */
  async add(base: string, paths: Readonly<Record<string, string>>, lastmod: Date | null): Promise<void> {
    const own = paths[this.locale];
    if (!own) return;
    const file = this.#current ?? this.#open();
    const { w } = file;
    w.open('url').leaf('loc', `${base}${own}`);
    if (lastmod) w.leaf('lastmod', lastmod.toISOString());
    for (const [l, p] of Object.entries(paths)) {
      w.leaf('xhtml:link', '', { rel: 'alternate', hreflang: l, href: `${base}${p}` });
    }
    const fallback = paths[DEFAULT_UI_LOCALE];
    if (fallback) w.leaf('xhtml:link', '', { rel: 'alternate', hreflang: 'x-default', href: `${base}${fallback}` });
    w.close().newline();
    file.urls += 1;
    if (w.pending >= FLUSH_CHARS) await file.sink.write(w.take());
    if (file.urls >= PORTAL_SITEMAP_URLS) await this.#finish();
  }

  async #finish(): Promise<void> {
    const file = this.#current;
    if (!file) return;
    this.#current = null;
    file.w.close();
    await file.sink.write(file.w.end());
    const result = await file.sink.finish();
    this.done.push({ name: file.name, sha256: result.sha256, bytes: result.bytes, urls: file.urls });
  }

  finish(): Promise<void> {
    return this.#finish();
  }

  async abort(): Promise<void> {
    await this.#current?.sink.abort();
    this.#current = null;
  }
}

type PortalDoc = { kind?: string; propertyType?: { id: string; name: string }; place?: Place };
type Place = Partial<Record<'country' | 'region' | 'city' | 'area', { id: string; name: string } | null>>;

const placeIdsOf = (place: Place | undefined): string[] =>
  place ? (['country', 'region', 'city', 'area'] as const).flatMap((k) => (place[k]?.id ? [place[k].id] : [])) : [];

export interface PortalSitemapRun {
  /** `superseded` (S16-F2): a newer run published while this one ran (a stalled job's retry); its files are gone. */
  skipped?: 'not-configured' | 'superseded';
  runId?: string;
  urls?: { listings: number; developments: number; places: number; agencies: number };
  files?: number;
}

/** Generates every sitemap file, the index and the manifest; then deletes the previous run's files. */
export async function generatePortalSitemaps(
  opts: { signal?: AbortSignal; log?: Logger; progress?: (urls: number) => Promise<void> } = {},
): Promise<PortalSitemapRun> {
  const base = origin;
  if (!base) return { skipped: 'not-configured' };
  const runId = newId();
  const generatedAt = clock.now();
  const locales = [...UI_LOCALES];
  const files = new Map<string, PartFiles>();
  const partOf = (locale: string, part: Part) => {
    const k = `${locale}|${part}`;
    let f = files.get(k);
    if (!f) {
      f = new PartFiles(runId, locale, part);
      files.set(k, f);
    }
    return f;
  };
  const add = async (part: Part, paths: Record<string, string>, lastmod: Date | null) => {
    for (const l of Object.keys(paths)) await partOf(l, part).add(base, paths, lastmod);
  };
  /** S16-F2: a part's walk is over — finish its open file in every locale (one open upload per locale at a time). */
  const finishPart = async (part: Part) => {
    for (const [k, f] of files) if (k.endsWith(`|${part}`)) await f.finish();
  };
  const counts = { listings: 0, developments: 0, places: 0, agencies: 0 };
  const seenPlaces = new Set<string>();
  /** S15-03: the agencies whose stock is listed (their profile pages). */
  const seenOwners = new Set<string>();
  const requestId = `portal-sitemaps:${runId}`;
  let written: PortalSitemapManifest['files'] = [];
  try {
    // 1. Listings: one keyset walk on the public-code index (the base locale's documents carry the ids); each locale's
    // URL from its own taxonomy names — the helper the listing pages use (`portalListingPaths`).
    const inventory = await portalInventory(requestId);
    const baseLocale = contentLocale(DEFAULT_UI_LOCALE);
    let after: string | undefined;
    while (inventory) {
      opts.signal?.throwIfAborted();
      const { rows, next } = await withPublicRead((tx) =>
        search.portalSitemapPage(tx, inventory, {
          after,
          limit: PORTAL_SITEMAP_BATCH,
          locale: baseLocale,
          fallback: fallbackOf(baseLocale),
        }),
      );
      for (const row of rows) {
        const code = row.publicCode;
        const doc = row.doc as PortalDoc;
        if (!code || doc.kind !== 'LISTING' || !doc.propertyType || !doc.place) continue;
        const paths = await portalListingPaths({ propertyType: doc.propertyType, place: doc.place }, code, locales);
        for (const id of placeIdsOf(doc.place)) seenPlaces.add(id);
        seenOwners.add(row.ownerAgencyId);
        await add('listings', paths, row.updatedAt);
        counts.listings += 1;
      }
      await opts.progress?.(counts.listings);
      if (next === null) break;
      after = next;
    }
    await finishPart('listings');

    // 2. Developments (newest first, keyset by code): one walk, one name for every locale (`portalDevelopmentPaths`).
    const devInventory = await developmentInventory(requestId);
    let afterDev: string | undefined;
    while (devInventory) {
      opts.signal?.throwIfAborted();
      const rows = await withPublicRead((tx) =>
        search.developmentPage(tx, devInventory, {
          after: afterDev,
          limit: DEVELOPMENT_BATCH,
          locale: baseLocale,
          fallback: fallbackOf(baseLocale),
        }),
      );
      const page = rows.slice(0, DEVELOPMENT_BATCH);
      for (const row of page) {
        const [card] = websites.serializeDevelopmentCards(ownView(row.ownerAgencyId, null), [
          { ...row, doc: row.doc as UnitCardDoc },
        ]);
        if (!card) continue;
        for (const id of placeIdsOf((row.doc as PortalDoc).place)) seenPlaces.add(id);
        seenOwners.add(row.ownerAgencyId);
        await add('developments', portalDevelopmentPaths(card, row.code, locales), row.updatedAt);
        counts.developments += 1;
      }
      const last = page[page.length - 1];
      if (rows.length <= DEVELOPMENT_BATCH || !last) break;
      afterDev = last.code;
    }
    await finishPart('developments');

    // 3. The home and search pages, and every location and zone page that holds any of it.
    await add('places', Object.fromEntries(locales.map((l) => [l, homePath(l)])), null);
    await add('places', Object.fromEntries(locales.map((l) => [l, searchPath(l)])), null);
    counts.places += 2;
    const indexes = new Map<string, PlaceIndex>();
    for (const l of locales) indexes.set(l, await placeIndex(contentLocale(l)));
    for (const id of seenPlaces) {
      const paths: Record<string, string> = {};
      for (const l of locales) {
        const node = indexes.get(l)?.byId.get(id);
        if (node) paths[l] = searchPath(l, node.path);
      }
      if (Object.keys(paths).length === 0) continue;
      await add('places', paths, null);
      counts.places += 1;
    }
    const baseIndex = indexes.get(DEFAULT_UI_LOCALE) ?? indexes.get(locales[0] as string);
    for (const zone of baseIndex?.zones.values() ?? []) {
      if (!zone.locationIds.some((id) => seenPlaces.has(id))) continue;
      const paths: Record<string, string> = {};
      for (const l of locales) {
        const slug = indexes.get(l)?.zoneById.get(zone.id)?.slug;
        if (slug) paths[l] = zonePath(l, slug);
      }
      await add('places', paths, null);
      counts.places += 1;
    }
    await finishPart('places');

    // S15-03: the profile pages of the listed agencies whose stock is above (directory names, one statement a batch).
    const owners = [...seenOwners].sort();
    for (let i = 0; i < owners.length; i += PORTAL_SITEMAP_BATCH) {
      opts.signal?.throwIfAborted();
      const batch = owners.slice(i, i + PORTAL_SITEMAP_BATCH);
      const found = await withPublicRead((tx) => agencies.publicAgencies(tx, batch));
      for (const id of batch) {
        const a = found.get(id);
        if (!a) continue;
        await add('agencies', portalAgencyPaths({ id, name: a.name }, locales), null);
        counts.agencies += 1;
      }
    }

    await finishPart('agencies');

    // 4. The index naming every part file (each finished when its walk ended).
    written = [...files.values()].flatMap((f) => f.done).sort((a, b) => (a.name < b.name ? -1 : 1));
    const index = new XmlWriter();
    index.open('sitemapindex', { xmlns: SITEMAP_NS }).newline();
    for (const f of written) {
      index.open('sitemap').leaf('loc', `${base}/sitemaps/${f.name}`).leaf('lastmod', generatedAt.toISOString());
      index.close().newline();
    }
    index.close();
    const indexSink = new GzipObjectUpload(
      storage().upload('feeds', fileKey(runId, PORTAL_SITEMAP_INDEX), { contentType: 'application/gzip' }),
      { hash: 'gzip', maxBytes: MAX_GZIP_BYTES, tooLarge: () => new Error('portal sitemap: index too large') },
    );
    await indexSink.write(index.end());
    const indexFile = await indexSink.finish();
    written.unshift({ name: PORTAL_SITEMAP_INDEX, sha256: indexFile.sha256, bytes: indexFile.bytes, urls: 0 });
  } catch (err) {
    for (const f of files.values()) await f.abort();
    await deleteRun(
      runId,
      [...written.map((f) => f.name), ...[...files.values()].flatMap((f) => f.done.map((d) => d.name))],
      opts.log,
    );
    throw err;
  }

  // 5. The run serves from here on. The previous run stays (public processes trust the manifest they read for up to
  // `MANIFEST_TTL_MS`); the run before it goes. S16-F2: published only over an older run's manifest, by a conditional
  // write — a stalled run that finishes after its own retry never replaces the newer manifest (whose sweep may have
  // removed the stalled run's early files).
  const published = await publishManifest(runId, generatedAt.toISOString(), written);
  if (!published) {
    await deleteRun(
      runId,
      written.map((f) => f.name),
      opts.log,
    );
    opts.log?.warn({ runId }, 'portal sitemaps superseded by a newer run: not published');
    return { skipped: 'superseded', runId };
  }
  const { manifest, current } = published;
  // The run before the previous one: named by the old manifest, complete, gone at once.
  const older = current?.previous;
  if (older && older.runId !== runId) await deleteRun(older.runId, older.files, opts.log);
  manifestCache = undefined;
  const swept = await sweepPortalSitemapRuns(manifest, opts.log);
  opts.log?.info({ runId, ...counts, files: written.length, swept }, 'portal sitemaps generated');
  return { runId, urls: counts, files: written.length };
}

/** Conditional manifest writes tried before giving up (each loses only to another run's write in between). */
const PUBLISH_TRIES = 5;

/**
 * S16-F2: writes the manifest naming this run unless the stored one is a newer run's (`generatedAt`, then `runId`:
 * UUIDv7, time-ordered) — `If-Match` on the ETag read, or `If-None-Match: *` when there is none, so no other run's
 * manifest is overwritten unseen. Null: superseded.
 */
async function publishManifest(
  runId: string,
  generatedAt: string,
  files: PortalSitemapManifest['files'],
): Promise<{ manifest: PortalSitemapManifest; current: PortalSitemapManifest | null } | null> {
  for (let attempt = 0; attempt < PUBLISH_TRIES; attempt += 1) {
    const head = await storage().head('feeds', MANIFEST_KEY);
    const current = head ? await readManifest() : null;
    if (
      current &&
      (current.generatedAt > generatedAt || (current.generatedAt === generatedAt && current.runId > runId))
    ) {
      return null;
    }
    const manifest: PortalSitemapManifest = {
      runId,
      generatedAt,
      files,
      ...(current && current.runId !== runId
        ? { previous: { runId: current.runId, files: current.files.map((f) => f.name) } }
        : {}),
    };
    const written = await storage().putIf(
      'feeds',
      MANIFEST_KEY,
      Buffer.from(JSON.stringify(manifest)),
      { contentType: 'application/json' },
      head ? { ifMatch: head.etag } : { ifNoneMatch: '*' },
    );
    if (written) return { manifest, current };
  }
  throw new Error('portal sitemaps: manifest kept changing; not published');
}

/** A run's files: `portal-sitemaps/<runId>/<name>.gz`. */
const RUN_KEY = /^portal-sitemaps\/([A-Za-z0-9_-]{1,64})\/[^/]+$/;
/** Run prefixes a sweep tracks at most (two kept runs, plus the leftovers of a few killed ones). */
const SWEEP_MAX_RUNS = 1_000;
/** The job's time limit (`websiteApi.generatePortalSitemaps`): a run older than this has been stopped by its worker. */
export const PORTAL_SITEMAP_TIMEOUT_MS = 60 * 60_000;
/**
 * How much older than the live run's oldest file an unnamed run's newest file must be to be swept: the job's time limit
 * plus 10 minutes (an abort lands at the next batch; storage timestamps are whole seconds, and a multipart object's is
 * its upload's start). Only a run that began over 70 minutes before the live run's first file can match — stopped by
 * then, whether it was killed or is a stalled job still running past its retry.
 */
const SWEEP_AGE_MS = PORTAL_SITEMAP_TIMEOUT_MS + 10 * 60_000;

/**
 * S16-F2: deletes every run prefix the manifest does not name (neither the live run nor the previous one) — the files
 * of a run killed mid-way (a dead worker never reaches its `catch`, so its finished part files stay; no manifest ever
 * names them). One listing of `portal-sitemaps/`, pages of 1,000 keys. A run is swept only when its newest file is
 * `SWEEP_AGE_MS` older than the live run's oldest file (both storage timestamps: no clock skew between worker and
 * store), so a run that may still be writing beside this one (a stalled job and its retry, either started first) is
 * left for a later sweep: a killed run's files go with the first run that starts over 70 minutes after it (the
 * schedule's next run, 6 hours on). Best effort: a failure is logged, the live run serves regardless. Returns the
 * number of files deleted.
 */
export async function sweepPortalSitemapRuns(manifest: PortalSitemapManifest, log?: Logger): Promise<number> {
  const keep = new Set([manifest.runId, ...(manifest.previous ? [manifest.previous.runId] : [])]);
  const runs = new Map<string, { keys: string[]; newest: number }>();
  let liveOldest = Number.POSITIVE_INFINITY;
  try {
    let after: string | undefined;
    do {
      const page = await storage().list('feeds', PORTAL_SITEMAP_PREFIX, { limit: 1_000, ...(after ? { after } : {}) });
      for (const o of page.objects) {
        const runId = RUN_KEY.exec(o.key)?.[1];
        if (!runId) continue;
        const at = o.lastModified.getTime();
        if (runId === manifest.runId) liveOldest = Math.min(liveOldest, at);
        if (keep.has(runId)) continue;
        let run = runs.get(runId);
        if (!run) {
          if (runs.size >= SWEEP_MAX_RUNS) continue;
          run = { keys: [], newest: 0 };
          runs.set(runId, run);
        }
        run.keys.push(o.key);
        run.newest = Math.max(run.newest, at);
      }
      after = page.next ?? undefined;
    } while (after);
  } catch (err) {
    log?.warn({ err: err instanceof Error ? err.name : 'error' }, 'portal sitemap runs not listed');
    return 0;
  }
  // The live run's files not listed (an eventually consistent listing): nothing to compare with — next run.
  if (!Number.isFinite(liveOldest)) return 0;
  let deleted = 0;
  for (const [runId, run] of runs) {
    if (run.newest >= liveOldest - SWEEP_AGE_MS) continue;
    for (const key of run.keys) {
      try {
        await storage().delete('feeds', key);
        deleted += 1;
      } catch (err) {
        // An orphan file is never served (the manifest names the live run only); the next sweep retries.
        log?.warn({ runId, err: err instanceof Error ? err.name : 'error' }, 'old portal sitemap file not deleted');
      }
    }
  }
  return deleted;
}

async function deleteRun(runId: string, names: readonly string[], log?: Logger): Promise<void> {
  for (const name of new Set(names)) {
    try {
      await storage().delete('feeds', fileKey(runId, name));
    } catch (err) {
      // An orphan file is never served (the manifest names the live run only).
      log?.warn({ runId, name, err: err instanceof Error ? err.name : 'error' }, 'old portal sitemap file not deleted');
    }
  }
}

async function readManifest(): Promise<PortalSitemapManifest | null> {
  const bytes = await storage().get('feeds', MANIFEST_KEY, { maxBytes: MANIFEST_MAX_BYTES });
  if (!bytes) return null;
  try {
    const m = JSON.parse(Buffer.from(bytes).toString('utf8')) as PortalSitemapManifest;
    return typeof m.runId === 'string' && Array.isArray(m.files) ? m : null;
  } catch {
    return null;
  }
}

// ── Serving (apps/public) ───────────────────────────────────────────────────────────────────────────────────────

/** How long a process trusts the manifest it read (a new run is picked up within this). */
const MANIFEST_TTL_MS = 60_000;
let manifestCache: { at: number; manifest: Promise<PortalSitemapManifest | null> } | undefined;
/**
 * S17-F39: a failed manifest read (storage slow or down) is remembered this long: requests in the window fail at once
 * (the caller answers 503) instead of each waiting for the storage timeout — a crawler burst never queues up behind a
 * dead store.
 */
const FAILURE_TTL_MS = 10_000;
let manifestFailedAt: number | undefined;

/** Tests: forget the cached manifest. */
export function resetPortalSitemapCache(): void {
  manifestCache = undefined;
  manifestFailedAt = undefined;
}

function currentManifest(): Promise<PortalSitemapManifest | null> {
  const now = Date.now();
  if (manifestFailedAt !== undefined && now - manifestFailedAt < FAILURE_TTL_MS) {
    return Promise.reject(new Error('portal sitemaps: storage unavailable'));
  }
  if (!manifestCache || now - manifestCache.at > MANIFEST_TTL_MS) {
    const manifest = readManifest();
    manifestCache = { at: now, manifest };
    manifest.catch(() => {
      manifestCache = undefined;
      manifestFailedAt = Date.now();
    });
  }
  return manifestCache.manifest;
}

export interface PortalSitemapFile {
  /** The stored gzip file's SHA-256 (base64url): the answer's ETag, per encoding (the caller's). */
  sha256: string;
  /** The file's gzip bytes (a storage read): only when the client has no current copy. */
  open(): Promise<Readable | null>;
}

/**
 * The live run's sitemap file `name` (`sitemap.xml`, or a part file) or null (not generated yet, or no such file).
 * No database statement: the manifest is read from storage at most once a minute per process.
 */
export async function portalSitemapFile(name: string): Promise<PortalSitemapFile | null> {
  if (name !== PORTAL_SITEMAP_INDEX && !PORTAL_SITEMAP_FILE.test(name)) return null;
  const manifest = await currentManifest();
  const file = manifest?.files.find((f) => f.name === name);
  if (!manifest || !file) return null;
  const key = fileKey(manifest.runId, name);
  return {
    sha256: file.sha256,
    open: () => storage().getStream('feeds', key, { maxBytes: MAX_GZIP_BYTES }),
  };
}
